keyframes_css.fade-up:
@keyframes fade-up { 
  0% { opacity: 0; transform: translateY(20px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes_css.fade-in:
@keyframes fade-in { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes_css.fadeSlideIn:
@keyframes fadeSlideIn { 
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes_css.slide-in-left:
@keyframes slide-in-left { 
  0% { opacity: 0; transform: translate(-20px); }
  100% { opacity: 1; transform: translate(0px); }
}

keyframes_css.slide-in-right:
@keyframes slide-in-right { 
  0% { opacity: 0; transform: translate(20px); }
  100% { opacity: 1; transform: translate(0px); }
}

keyframes_css.slide-in-center:
@keyframes slide-in-center { 
  0% { opacity: 0; transform: scale(0.8) translateY(10px); }
  100% { opacity: 1; transform: scale(1) translateY(0px); }
}

keyframes_css.scrollDot:
@keyframes scrollDot { 
  0%, 100% { opacity: 0.4; transform: translateY(0px); }
  50% { opacity: 1; transform: translateY(8px); }
}

keyframes_css.indeterminate:
@keyframes indeterminate { 
  0% { width: 0%; margin-left: 0px; }
  50% { width: 60%; margin-left: 20%; }
  100% { width: 0%; margin-left: 100%; }
}

keyframes_css.scaleOutPulse:
@keyframes scaleOutPulse { 
  0% { transform: translate(-50%,-50%)scale(var(--pulse-scale-start)); opacity: var(--pulse-opacity-start); }
  100% { transform: translate(-50%,-50%)scale(var(--pulse-scale-end)); opacity: var(--pulse-opacity-end); }
}

keyframes_css.slideDown:
@keyframes slideDown { 
  0% { opacity: 0; transform: translateY(-10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes_css.megaReveal:
@keyframes megaReveal { 
  0% { opacity: 0; max-height: 0px; transform: translateY(-8px); }
  40% { opacity: 1; }
  100% { opacity: 1; max-height: 600px; transform: translateY(0px); }
}

keyframes_css.bloom:
@keyframes bloom { 
  0% { opacity: 0; transform: scale(0.4) rotate(-8deg); }
  70% { opacity: 1; transform: scale(1.05) rotate(3deg); }
  100% { opacity: 1; transform: scale(1) rotate(0deg); }
}

keyframes_css.float1:
@keyframes float1 { 
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-10px) rotate(3deg); }
}

keyframes_css.float2:
@keyframes float2 { 
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  33% { transform: translateY(-8px) rotate(-2deg); }
  66% { transform: translateY(-12px) rotate(4deg); }
}

keyframes_css.float3:
@keyframes float3 { 
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  40% { transform: translateY(-6px) rotate(2deg); }
  80% { transform: translateY(-14px) rotate(-3deg); }
}

keyframes_css.shimmer:
@keyframes shimmer { 
  0% { transform: translate(-100%); }
  40% { transform: translate(100%); }
  100% { transform: translate(100%); }
}

keyframes_css.wiggle:
@keyframes wiggle { 
  0%, 100% { rotate: none; }
  20% { rotate: -1.5deg; }
  40% { rotate: 1.2deg; }
  60% { rotate: -0.8deg; }
  80% { rotate: 0.5deg; }
}

keyframes_css.arrow-loop:
@keyframes arrow-loop { 
  0% { opacity: 1; transform: translate(0px); }
  35% { opacity: 0; transform: translate(14px); }
  36% { opacity: 0; transform: translate(-14px); }
  100% { opacity: 1; transform: translate(0px); }
}

keyframes_css.textCrawl:
@keyframes textCrawl { 
  0%, 15% { transform: translate(0px); }
  45%, 55% { transform: translate(var(--marquee-offset,0)); }
  85%, 100% { transform: translate(0px); }
}

keyframes_css.launch-pill-jump:
@keyframes launch-pill-jump { 
  0% { transform: translateY(0px); }
  30% { transform: translateY(-0.45rem); }
  60% { transform: translateY(0.05rem); }
  100% { transform: translateY(0px); }
}

keyframes_css.live-transcript-from-agent:
@keyframes live-transcript-from-agent { 
  0% { opacity: 0; clip-path: inset(0px 100% 0px 0px round 0.75rem); transform: translate(-0.55rem); }
  100% { opacity: 1; clip-path: inset(0px round 0.75rem); transform: translate(0px); }
}

keyframes_css.live-transcript-from-caller:
@keyframes live-transcript-from-caller { 
  0% { opacity: 0; clip-path: inset(0px 0px 0px 100% round 0.75rem); transform: translate(0.55rem); }
  100% { opacity: 1; clip-path: inset(0px round 0.75rem); transform: translate(0px); }
}

keyframes_css.connecting-status:
@keyframes connecting-status { 
  0%, 100% { opacity: 0.45; transform: scale(0.88); }
  50% { opacity: 1; transform: scale(1); }
}

keyframes_css.ask-word-exit:
@keyframes ask-word-exit { 
  0% { opacity: 1; filter: blur(); transform: translateY(0px); }
  40% { opacity: 0; filter: blur(4px); }
  100% { opacity: 0; filter: blur(4px); transform: translateY(-80%); }
}

keyframes_css.ask-word-enter:
@keyframes ask-word-enter { 
  0% { opacity: 0; filter: blur(3px); transform: translateY(100%); }
  100% { opacity: 1; filter: blur(); transform: translateY(0px); }
}

keyframes_css.ask-dot-pulse:
@keyframes ask-dot-pulse { 
  0%, 80%, 100% { opacity: 0.3; transform: scale(0.8); }
  40% { opacity: 1; transform: scale(1); }
}

keyframes_css.ask-logo-pulse:
@keyframes ask-logo-pulse { 
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.08); }
}

keyframes_css.ask-viz-enter:
@keyframes ask-viz-enter { 
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes_css.voice-buddy-wobble:
@keyframes voice-buddy-wobble { 
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(-5deg); }
  75% { transform: rotate(5deg); }
}

keyframes_css.voice-buddy-z:
@keyframes voice-buddy-z { 
  0% { opacity: 0; transform: translate(0px) scale(0.6); }
  25% { opacity: 1; }
  100% { opacity: 0; transform: translate(2.5px, -6px) scale(1.15); }
}

keyframes_css.voice-buddy-pop:
@keyframes voice-buddy-pop { 
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.7); }
}

keyframes_css.voice-buddy-droplet:
@keyframes voice-buddy-droplet { 
  0% { opacity: 1; transform: translate(0px); }
  100% { transform: translate(var(--dx),var(--dy)); opacity: 0; }
}

keyframes_css.voice-buddy-stretch:
@keyframes voice-buddy-stretch { 
  0% { transform: none; }
  14% { transform: scale(1.08, 0.88); }
  34% { transform: translateY(-3px) scale(0.93, 1.1); }
  50% { transform: rotate(-7deg); }
  62% { transform: rotate(6deg); }
  74% { transform: rotate(-4deg); }
  86% { transform: rotate(2deg); }
  100% { transform: none; }
}

keyframes_css.voice-word-in:
@keyframes voice-word-in { 
  0% { opacity: 0; filter: blur(2px); transform: translateY(3px); }
  100% { opacity: 1; filter: blur(); transform: none; }
}

keyframes_css.voice-buddy-wake:
@keyframes voice-buddy-wake { 
  0% { opacity: 0; transform: translateY(28px) scale(0.55); }
  60% { opacity: 1; transform: translateY(-4px) scale(1.06); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

keyframes_css.voice-typing-dot:
@keyframes voice-typing-dot { 
  0%, 60%, 100% { opacity: 0.45; transform: translateY(0px); }
  30% { opacity: 1; transform: translateY(-3px); }
}

keyframes_css.voice-buddy-scribble:
@keyframes voice-buddy-scribble { 
  0%, 100% { transform: translate(0px) rotate(0deg); }
  25% { transform: translate(1.5px, -1px) rotate(-6deg); }
  50% { transform: translate(-0.5px, 0.5px) rotate(3deg); }
  75% { transform: translate(1px, 0.8px) rotate(-3deg); }
}

keyframes_css.dts-swap:
@keyframes dts-swap { 
  0% { opacity: 0; filter: blur(6px); transform: translateY(6px); }
  100% { opacity: 1; filter: blur(); transform: none; }
}

keyframes_css.dt-reveal:
@keyframes dt-reveal { 
  0% { opacity: 0; transform: translateY(28px) scale(0.985); }
  100% { opacity: 1; transform: none; }
}

keyframes_css.csc-drift:
@keyframes csc-drift { 
  0%, 100% { transform: translateY(-50%) scale(1); }
  50% { transform: translate(6%, -54%) scale(1.12); }
}

keyframes_css.csc-poster-rise:
@keyframes csc-poster-rise { 
  0% { opacity: 0; transform: translateY(16px) scale(0.96); }
  100% { opacity: 1; transform: translate(0px) scale(1); }
}

keyframes_css.typing:
@keyframes typing { 
  0%, 60%, 100% { opacity: 0.5; transform: translateY(0px); }
  30% { opacity: 1; transform: translateY(-6px); }
}

keyframes_css.popIn:
@keyframes popIn { 
  0% { opacity: 0; transform: scale(0.85); }
  100% { opacity: 1; transform: scale(1); }
}

keyframes_css.tf-uc-code-band:
@keyframes tf-uc-code-band { 
  0%, 8% { opacity: 0; transform: scaleX(0); }
  24%, 86% { opacity: 1; transform: scaleX(1); }
  96%, 100% { opacity: 0; transform: scaleX(1); }
}

keyframes_css.tf-uc-code-status:
@keyframes tf-uc-code-status { 
  0%, 34% { opacity: 0; transform: translateY(4px); }
  42%, 86% { opacity: 1; transform: translateY(0px); }
  96%, 100% { opacity: 0; transform: translateY(0px); }
}

keyframes_css.tf-uc-lens:
@keyframes tf-uc-lens { 
  0%, 100% { transform: translate(0px); }
  35% { transform: translate(72px, -14px); }
  65% { transform: translate(48px, 30px); }
}

keyframes_css.tf-uc-twinkle:
@keyframes tf-uc-twinkle { 
  0%, 100% { opacity: 0.3; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1); }
}
